INSERT INTO `lime_group_l10ns` VALUES (1,1,'My first question group','','en'),(2,2,'Textfragen','r453q26ier steht die Beschreibung für die Gruppe der Textfragen.','de-informal'),(3,2,'Text question','This is the description for text question group.','en'),(4,2,'Question de type texte','Ceci est la description du groupe de questions de type texte.','fr'),(5,2,'Domande di tipo Testo','Questa è la descrizione per questo gruppo.','it'),(6,2,'Текстовый вопрос','Это описание для группы текстовых вопросов.','ru'),(7,3,'Numerische Fragen','r453q26ier steht die Beschreibung für die Gruppe der numerischen Fragen.','de-informal'),(8,3,'Numeric question','This is the description for numeric question group.','en'),(9,3,'Question de type numérique','Ceci est la description des questions de type numérique','fr'),(10,3,'Domande numeriche','Questa è la descrizione del gruppo di domande numeriche','it'),(11,3,'Числовой вопрос','Это описание для группы числовых вопросов.','ru'),(12,4,'Einfachauswahl','r453q26ier steht die Beschreibung für die Gruppe der Einfachauswahl-Fragen.','de-informal'),(13,4,'Single choice question','The single choice questions group description','en'),(14,4,'Question à réponse unique','Ceci est la description du groupe des questions à réponse unique','fr'),(15,4,'Domande a scelta singola','Descrizione del gruppo dedicato alle Domande a scelta singola','it'),(16,4,'Вопрос с единственным выбором','<p>Описание группы вопросов с одним вариантом ответа</p>\n','ru'),(17,5,'Mehrfachauswahl','r453q26ier steht die Beschreibung für die Gruppe der Mehrfachauswahl-Fragen.','de-informal'),(18,5,'Multi choice question','This is the description for multi choice question','en'),(19,5,'QSuestions à réponses multiples','Ceci est la description du groupe des questions à réponses multiples','fr'),(20,5,'Domande a scelta multipla','Questa è la descrizione del gruppo di domande a scelta multipla','it'),(21,5,'Вопрос с несколькими вариантами ответов','Это описание вопроса с несколькими вариантами ответов','ru'),(22,6,'Bedingungen und Filter','<p>Limesurvey unterstützt eine Vielzahl von Bedingungen und Filtern zum Anzeigen und Vestecken von Fragen. Dies umfasst Bedingungen mit UND- sowie ODER-Verknüpfungen. Weitere Informationen finden sich in der <small><a href=\"manual.limesurvey.org/Conditions_Engine\" lang=\"en\" target=\"_blank\">LimeSurvey Dokumentation</a></small>.</p>\n','de-informal'),(23,6,'Condition and scenario','<p>LimeSurvey can use a lot of condition and filter to show or hide question. You an use AND or OR condition. You can use previous question answers and tokens.</p>\n\n<p><small>More information : <a href=\"http://manual.limesurvey.org/Conditions_Engine\">Conditions Engine</a> and <a href=\"http://manual.limesurvey.org/Expression_Manager\">expression manager</a></small></p>\n','en'),(24,6,'Conditions and scenario','<p>LimeSurvey peut utiliser de nombreuses conditions et filtres pour masquer certaines questions. Il est possible d\'utiliser des conditions de type OR ou AND. Vous pouvez utiliser les réponses précédentes mais aussi les attributs des invitations.</p>\n\n<p><small>Plus d\'informations : <a href=\"http://manual.limesurvey.org/Conditions_Engine\">le gestionnaire de conditions</a> et le <a href=\"http://manual.limesurvey.org/Expression_Manager\">gestionnaire d\'expressions</a></small></p>\n','fr'),(25,6,'Condizioni e scenari','<p>LimeSurvey consente l\'utilizzo di molte condizioni e filtri per nascondere e mostrare domande. Puoi usare le condizioni in AND e in OR, e utilizzare le risposte fornite alle domande precedenti oppure le informazioni dei partecipanti (tokens).</p>\n<small>Ulteriori informazioni : <a href=\"http://manual.limesurvey.org/Conditions_Engine\">Conditions Engine</a> e <a href=\"http://manual.limesurvey.org/Expression_Manager\">expression manager</a></small>','it'),(26,6,'Условия и сценарий','<p>LimeSurvey может использовать множество условий и фильтров для показа или скрытия вопросов. Можно использовать условия AND или OR. Можно использовать ответы на предыдущие вопросы и маркеры.</p>\n\n<p>Дополнительная информация: <a href=\"http://manual.limesurvey.org/Conditions_Engine\">механизм условий</a> и <a href=\"http://manual.limesurvey.org/Expression_Manager&quot;\">менеджер выражений</a></p>\n','ru'),(27,7,'Filter','Antwortoptionen von Folgefragen können durch das Frageattribut <a href=\"http://manual.limesurvey.org/QS:Array_filter\" lang=\"en\" target=\"_blank\">Array Filter</a><a> und </a><a href=\"http://manual.limesurvey.org/Array_filter_exclude\" lang=\"en\" target=\"_blank\">Array Filter Exclusion</a> gefiltert werden.','de-informal'),(28,7,'Filter','You can display/hide subquestion with <a href=\"http://manual.limesurvey.org/QS:Array_filter\" lang=\"en\" target=\"_blank\">Array Filter</a> and <a href=\"http://manual.limesurvey.org/QS:Array_filter_exclude\" lang=\"en\" target=\"_blank\">Array Filter Exclusion</a>. We use Expression Manager to hide and show question too.','en'),(29,7,'Filtres de tableaux','Vous pouvez afficher ou masquer une série de sous question avec l\'attribut <a href=\"http://manual.limesurvey.org/QS:Array_filter\" lang=\"en\" target=\"_blank\">Filtre de tableau</a> et <a href=\"http://manual.limesurvey.org/QS:Array_filter_exclude\" lang=\"en\" target=\"_blank\">Filttre d’exclusion</a>. On utilise le gestionnaire d\'expression pour masquer ou montrer les questions correspondantes.','fr'),(30,7,'Filtri','E\' possibile nascondere/mostrare sottodomande usando i <a href=\"http://manual.limesurvey.org/QS:Array_filter\" lang=\"en\" target=\"_blank\">Filtri Array</a> and <a href=\"http://manual.limesurvey.org/QS:Array_filter_exclude\" lang=\"en\" target=\"_blank\">Filtri Array di Esclusione</a>. Useremo anche l\'Expression Manager per nascondere e mostrare domande.','it'),(31,7,'Фильтр','Вы можете отображать/скрывать подвопросы с помощью фильтров <a href=\"http://manual.limesurvey.org/QS:Array_filter\">Array Filter</a> и <a href=\"http://manual.limesurvey.org/QS:Array_filter_exclude\">Array Filter Exclusion</a>. Для скрытия и отображения вопросов мы также используем менеджер выражений.','ru');
/*!40000 ALTER TABLE `lime_group_l10ns` ENABLE KEYS */;
UNLOCK TABLES;

