INSERT INTO `lime_surveys_languagesettings` VALUES (952972,'en','Default survey','','','<p>Thank you for taking this survey!</p>','','','','','','Invitation to participate in a survey','Dear {FIRSTNAME},<br />\n<br />\nYou have been invited to participate in a survey.<br />\n<br />\nThe survey is titled:<br />\n\"{SURVEYNAME}\"<br />\n<br />\n\"{SURVEYDESCRIPTION}\"<br />\n<br />\nTo participate, please click on the link below.<br />\n<br />\nSincerely,<br />\n<br />\n{ADMINNAME} ({ADMINEMAIL})<br />\n<br />\n----------------------------------------------<br />\nClick here to do the survey:<br />\n{SURVEYURL}<br />\n<br />\nIf you do not want to participate in this survey and don\'t want to receive any more invitations please click the following link:<br />\n{OPTOUTURL}<br />\n<br />\nIf you are blocklisted but want to participate in this survey and want to receive invitations please click the following link:<br />\n{OPTINURL}','Reminder to participate in a survey','Dear {FIRSTNAME},<br />\n<br />\nRecently we invited you to participate in a survey.<br />\n<br />\nWe note that you have not yet completed the survey, and wish to remind you that the survey is still available should you wish to take part.<br />\n<br />\nThe survey is titled:<br />\n\"{SURVEYNAME}\"<br />\n<br />\n\"{SURVEYDESCRIPTION}\"<br />\n<br />\nTo participate, please click on the link below.<br />\n<br />\nSincerely,<br />\n<br />\n{ADMINNAME} ({ADMINEMAIL})<br />\n<br />\n----------------------------------------------<br />\nClick here to do the survey:<br />\n{SURVEYURL}<br />\n<br />\nIf you do not want to participate in this survey and don\'t want to receive any more invitations please click the following link:<br />\n{OPTOUTURL}','Survey registration confirmation','Dear {FIRSTNAME},<br />\n<br />\nYou, or someone using your email address, have registered to participate in an online survey titled {SURVEYNAME}.<br />\n<br />\nTo complete this survey, click on the following URL:<br />\n<br />\n{SURVEYURL}<br />\n<br />\nIf you have any questions about this survey, or if you did not register to participate and believe this email is in error, please contact {ADMINNAME} at {ADMINEMAIL}.','Confirmation of your participation in our survey','Dear {FIRSTNAME},<br />\n<br />\nThis email is to confirm that you have completed the survey titled {SURVEYNAME} and your response has been saved. Thank you for participating.<br />\n<br />\nIf you have any further questions about this email, please contact {ADMINNAME} on {ADMINEMAIL}.<br />\n<br />\nSincerely,<br />\n<br />\n{ADMINNAME}',9,NULL,'','Response submission for survey {SURVEYNAME}','Hello,<br />\n<br />\nA new response was submitted for your survey \'{SURVEYNAME}\'.<br />\n<br />\nClick the following link to see the individual response:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nClick the following link to edit the individual response:<br />\n{EDITRESPONSEURL}<br />\n<br />\nView statistics by clicking here:<br />\n{STATISTICSURL}','Response submission for survey {SURVEYNAME} with results','Hello,<br />\n<br />\nA new response was submitted for your survey \'{SURVEYNAME}\'.<br />\n<br />\nClick the following link to see the individual response:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nClick the following link to edit the individual response:<br />\n{EDITRESPONSEURL}<br />\n<br />\nView statistics by clicking here:<br />\n{STATISTICSURL}<br />\n<br />\n<br />\nThe following answers were given by the participant:<br />\n{ANSWERTABLE}',0,NULL),(282267,'de-informal','Beispielfragebogen für Limesurvey EN/FR/DE/RU','Dieser Beispielfragebogen demonstriert alle in Limesurvey vorhanden Fragetypen sowie zusätzliche Frageoptionen.','<p>Dies ist die Willkommensnachricht des Fragebogens. Sie kann unter Fragebogeneinstellungen -> Texte angepasst werden.</p>\n','','','','','http://www.limesurvey.org','','Einladung zur einer Umfrage','Hallo {FIRSTNAME},\n\nHiermit möchten wir dich zu einer Umfrage einladen.\n\nDer Titel der Umfrage ist \n\'{SURVEYNAME}\'\n\n\'{SURVEYDESCRIPTION}\'\n\nUm an dieser Umfrage teilzunehmen, klicke bitte auf den unten stehenden Link.\n\nMit freundlichen Grüßen,\n\n{ADMINNAME} ({ADMINEMAIL})\n\n----------------------------------------------\nKlicke hier um die Umfrage zu starten:\n{SURVEYURL}\n\nWenn Du an dieser Umfrage nicht teilnehmen und keine weiteren Erinnerungen erhalten möchtest, klicke bitte auf den folgenden Link:\n{OPTOUTURL}','Erinnerung an die Teilnahme an einer Umfrage','Hallo {FIRSTNAME},\n\nVor kurzem haben wir Dich zu einer Umfrage eingeladen.\n\nZu unserem Bedauern haben wir bemerkt, dass Du die Umfrage noch nicht ausgefüllt hast. Wir möchten Dir mitteilen, dass die Umfrage noch aktiv ist und würden uns freuen, wenn Du teilnehmen könntest.\n\nDer Titel der Umfrage ist \n\'{SURVEYNAME}\'\n\n\'{SURVEYDESCRIPTION}\'\n\nUm an dieser Umfrage teilzunehmen, klicke bitte auf den unten stehenden Link.\n\n Mit freundlichen Grüßen,\n\n{ADMINNAME} ({ADMINEMAIL})\n\n----------------------------------------------\nKlicken Du hier um die Umfrage zu starten:\n{SURVEYURL}\n\nWenn Du an dieser Umfrage nicht teilnehmen und keine weiteren Erinnerungen erhalten möchtest, klicke bitte auf den folgenden Link:\n{OPTOUTURL}','Registrierungsbestätigung für Teilnahmeumfrage','Hallo {FIRSTNAME},\n\nDu (oder jemand, der Deine E-Mail benutzt hat) hat sich für eine Umfrage mit dem Titel {SURVEYNAME} angemeldet.\n\nUm an dieser Umfrage teilzunehmen, klicke bitte auf den folgenden Link.nn{SURVEYURL}\n\nWenn Du irgendwelche Fragen zu dieser Umfrage hast oder wenn Du Dich _nicht_ für diese Umfrage angemeldet hast und Du glaubst, dass Dir diese E-Mail irrtümlicherweise zugeschickt worden ist, kontaktiere bitte {ADMINNAME} unter {ADMINEMAIL}.','Bestätigung für die Teilnahme an unserer Umfrage','Hallo {FIRSTNAME},\n\nVielen Dank für die Teilnahme an der Umfrage mit dem Titel {SURVEYNAME}. Deine Antworten wurden bei uns gespeichert.\n\nWenn du irgendwelche Fragen zu dieser E-Mail hast, kontaktiere bitte {ADMINNAME} unter {ADMINEMAIL}.\n\nMit freundlichen Grüßen,\n\n{ADMINNAME}',1,NULL,'','Antwortabsendung für Umfrage {SURVEYNAME}','Hallo,\n\nEine neue Antwort wurde für die Umfrage \'{SURVEYNAME}\' abgegeben.\n\nKlicke auf den folgenden Link um die Umfrage neu zu laden:\n{RELOADURL}\n\nKlicke auf den folgenden Link um den Antwortdatensatz anzusehen:\n{VIEWRESPONSEURL}\n\nKlicke auf den folgenden Link um den Antwortdatensatz zu bearbeiten:\n{EDITRESPONSEURL}\n\nUm die Statistik zu sehen, klicke hier:\n{STATISTICSURL}','Antwortabsendung für Umfrage %s','<style type=\"text/css\">\n                                                .printouttable {\n                                                  margin:1em auto;\n                                                }\n                                                .printouttable th {\n                                                  text-align: center;\n                                                }\n                                                .printouttable td {\n                                                  border-color: #ddf #ddf #ddf #ddf;\n                                                  border-style: solid;\n                                                  border-width: 1px;\n                                                  padding:0.1em 1em 0.1em 0.5em;\n                                                }\n\n                                                .printouttable td:first-child {\n                                                  font-weight: 700;\n                                                  text-align: right;\n                                                  padding-right: 5px;\n                                                  padding-left: 5px;\n\n                                                }\n                                                .printouttable .printanswersquestion td{\n                                                  background-color:#F7F8FF;\n                                                }\n\n                                                .printouttable .printanswersquestionhead td{\n                                                  text-align: left;\n                                                  background-color:#ddf;\n                                                }\n\n                                                .printouttable .printanswersgroup td{\n                                                  text-align: center;        \n                                                  font-weight:bold;\n                                                  padding-top:1em;\n                                                }\n                                                </style>Hallo,\n\nEine neue Antwort wurde für die Umfrage \'{SURVEYNAME}\' abgegeben.\n\nKlicke auf den folgenden Link um die Umfrage neu zu laden:\n{RELOADURL}\n\nKlicke auf den folgenden Link um den Antwortdatensatz anzusehen:\n{VIEWRESPONSEURL}\n\nKlicke auf den folgenden Link um den Antwortdatensatz zu bearbeiten:\n{EDITRESPONSEURL}\n\nUm die Statistik zu sehen, klicke hier:\n{STATISTICSURL}\n\n\nDie folgenden Antworten wurden vom Teilnehmer gegeben:\n{ANSWERTABLE}',0,NULL),(282267,'en','Sample LimeSurvey EN/FR/DE/IT/RU','This survey show all question type of LimeSurvey with some option','<p>This is the welcome text for the survey! You can can edit it in the survey properties.</p>\n','<p>This is the end message for the survey! A good place to thank you to answer to this survey.</p>\n','','','','http://www.limesurvey.org','The end URL description of your survey. This URL can be automatically load when survey is completed.','Invitation to participate in survey','Dear {FIRSTNAME},<br /><br />You have been invited to participate in a survey.<br /><br />The survey is titled:<br />\"{SURVEYNAME}\"<br /><br />\"{SURVEYDESCRIPTION}\"<br /><br />To participate, please click on the link below.<br /><br />Sincerely,<br /><br />{ADMINNAME} ({ADMINEMAIL})<br /><br />----------------------------------------------<br />Click here to do the survey:<br />{SURVEYURL}<br /><br />If you do not want to participate in this survey and don\'t want to receive any more invitations please click the following link:<br />{OPTOUTURL}','Reminder to participate in survey','Dear {FIRSTNAME},<br /><br />Recently we invited you to participate in a survey.<br /><br />We note that you have not yet completed the survey, and wish to remind you that the survey is still available should you wish to take part.<br /><br />The survey is titled:<br />\"{SURVEYNAME}\"<br /><br />\"{SURVEYDESCRIPTION}\"<br /><br />To participate, please click on the link below.<br /><br />Sincerely,<br /><br />{ADMINNAME} ({ADMINEMAIL})<br /><br />----------------------------------------------<br />Click here to do the survey:<br />{SURVEYURL}<br /><br />If you do not want to participate in this survey and don\'t want to receive any more invitations please click the following link:<br />{OPTOUTURL}','Survey registration confirmation','Dear {FIRSTNAME},<br /><br />You, or someone using your email address, have registered to participate in an online survey titled {SURVEYNAME}.<br /><br />To complete this survey, click on the following URL:<br /><br />{SURVEYURL}<br /><br />If you have any questions about this survey, or if you did not register to participate and believe this email is in error, please contact {ADMINNAME} at {ADMINEMAIL}.','Confirmation of completed survey','Dear {FIRSTNAME},<br /><br />This email is to confirm that you have completed the survey titled {SURVEYNAME} and your response has been saved. Thank you for participating.<br /><br />If you have any further questions about this email, please contact {ADMINNAME} at {ADMINEMAIL}.<br /><br />Sincerely,<br /><br />{ADMINNAME}',5,NULL,'','Response submission for survey {SURVEYNAME}','Hello,<br />\n<br />\nA new response was submitted for your survey \'{SURVEYNAME}\'.<br />\n<br />\nClick the following link to reload the survey:<br />\n{RELOADURL}<br />\n<br />\nClick the following link to see the individual response:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nClick the following link to edit the individual response:<br />\n{EDITRESPONSEURL}<br />\n<br />\nView statistics by clicking here:<br />\n{STATISTICSURL}','Response submission for survey {SURVEYNAME} with results','Hello,<br />\n<br />\nA new response was submitted for your survey \'{SURVEYNAME}\'.<br />\n<br />\nClick the following link to reload the survey:<br />\n{RELOADURL}<br />\n<br />\nClick the following link to see the individual response:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nClick the following link to edit the individual response:<br />\n{EDITRESPONSEURL}<br />\n<br />\nView statistics by clicking here:<br />\n{STATISTICSURL}<br />\n<br />\n<br />\nThe following answers were given by the participant:<br />\n{ANSWERTABLE}',0,NULL),(282267,'fr','Exemple de questionnaire EN/FR/DE/RU','Ce sondage montre toutes les types de questions de LimeSurvey et quelques options.','<p>Ceci est le message d\'accueil de votre sondage !! Vous pouvez l\'éditer dans les paramètres du questionnaire.</p>\n','<p>Ceci est le message de fin de votre questionnaire ! Un bon endroit pour vous remercier d\'avoir répondu à ce questionnaire.</p>\n','','','','http://www.limesurvey.org','La description de l\'URL de fin, ce sondage est distribué sous Licence GPL','Invitation à participer à un questionnaire','Cher(e) {FIRSTNAME},<br /><br />Vous avez été invité à participer à un questionnaire.<br /><br />Celui-ci est intitulé :<br />\"{SURVEYNAME}\"<br /><br />\"{SURVEYDESCRIPTION}\"<br /><br />Pour participer, veuillez cliquer sur le lien ci-dessous.<br /><br />Cordialement,<br /><br />{ADMINNAME} ({ADMINEMAIL})<br /><br />----------------------------------------------<br />Cliquez ici pour remplir ce questionnaire :<br />{SURVEYURL}<br /><br />Si vous ne souhaitez pas participer à ce questionnaire et ne souhaitez plus recevoir aucune invitation, veuillez cliquer sur le lien suivant :<br />{OPTOUTURL}','Rappel pour participer à un questionnaire','Cher(e) {FIRSTNAME},<br /><br />Vous avez été invité à participer à un questionnaire récemment.<br /><br />Nous avons pris en compte que vous n\'avez pas encore complété le questionnaire, et nous vous rappelons que celui-ci est toujours disponible si vous souhaitez participer.<br /><br />Le questionnaire est intitulé :<br />\"{SURVEYNAME}\"<br /><br />\"{SURVEYDESCRIPTION}\"<br /><br />Pour participer, veuillez cliquer sur le lien ci-dessous.<br /><br />Cordialement,<br /><br />{ADMINNAME} ({ADMINEMAIL})<br /><br />----------------------------------------------<br />Cliquez ici pour faire le questionnaire:<br />{SURVEYURL}<br /><br />Si vous ne souhaitez pas participer à ce questionnaire et ne souhaitez plus recevoir aucune invitation, veuillez cliquer sur le lien suivant :<br />{OPTOUTURL}','Confirmation de l\'inscription au questionnaire','Cher(e){FIRSTNAME},<br /><br />Vous (ou quelqu\'un utilisant votre adresse électronique) vous êtes enregistré pour participer à un questionnaire en ligne intitulé {SURVEYNAME}.<br /><br />Pour compléter ce questionnaire, cliquez sur le lien suivant :<br /><br />{SURVEYURL}<br /><br />Si vous avez des questions à propos de ce questionnaire, ou si vous ne vous êtes pas enregistré pour participer à celui-ci et croyez que ce courriel est une erreur, veuillez contacter {ADMINNAME} sur {ADMINEMAIL}','Confirmation de questionnaire complété','Cher(e) {FIRSTNAME},<br /><br />Ce courriel vous confirme que vous avez complété le questionnaire intitulé {SURVEYNAME} et que votre réponse a été enregistrée. Merci pour votre participation.<br /><br />Si vous avez des questions à propos de ce courriel, veuillez contacter {ADMINNAME} sur {ADMINEMAIL}.<br /><br />Cordialement,<br /><br />{ADMINNAME}',5,NULL,'','Soumission de réponse pour le questionnaire {SURVEYNAME}','Bonjour,<br />\n<br />\nUne nouvelle réponse a été soumise pour votre questionnaire \'{SURVEYNAME}\'.<br />\n<br />\nCliquer sur le lien suivant pour recharger votre questionnaire :<br />\n{RELOADURL}<br />\n<br />\nCliquer sur le lien suivant pour voir la réponse :<br />\n{VIEWRESPONSEURL}<br />\n<br />\nCliquer sur le lien suivant pour éditer la réponse :<br />\n{EDITRESPONSEURL}<br />\n<br />\nVisualiser les statistiques en cliquant ici :<br />\n{STATISTICSURL}<br />\n<br />\nles réponses suivantes ont été données par le participant :<br />\n{ANSWERTABLE}','Soumission de réponse pour le questionnaire {SURVEYNAME} avec résultats','Bonjour,<br />\n<br />\nUne nouvelle réponse a été soumise pour votre questionnaire \'{SURVEYNAME}\'.<br />\n<br />\nCliquer sur le lien suivant pour recharger votre questionnaire :<br />\n{RELOADURL}<br />\n<br />\nCliquer sur le lien suivant pour voir la réponse :<br />\n{VIEWRESPONSEURL}<br />\n<br />\nCliquez sur le lien suivant pour éditer la réponse individuelle :<br />\n{EDITRESPONSEURL}<br />\n<br />\nVisualiser les statistiques en cliquant ici :<br />\n{STATISTICSURL}<br />\n<br />\n<br />\nles réponses suivantes ont été données par le participant :<br />\n{ANSWERTABLE}',1,NULL),(282267,'it','Sample LimeSurvey EN/FR/DE/IT/RU','Questa indagine presenta tutti i tipi di domanda di LimeSurvey con alcune opzioni aggiuntive','<p>Questo è il messaggio di benvenuto dell\'indagine!!!</p>\n\n<p>E\' possibile modificarlo nelle impostazioni di indagine</p>\n\n<p> </p>\n','<p>Questo è il messaggio di chiusura dell\'indagine, dopo che il rispondente ha premuto INVIA.</p>\n\n<p>E\' possibile modificarlo nelle impostazioni di indagine</p>\n','Questo è il messaggio sui termini dei dati dell\'indagine','Questo è il messaggio di errore sui termini dei dati dell\'indagine','Questa etichetta spiega i termini dei dati di indagine','','','Invito per partecipare all\'indagine','Egregio/a {FIRSTNAME},<br />\n<br />\nè invitato a partecipare ad un\'indagine on line.<br />\n<br />\nL\'indagine è intitolata:<br />\n\"{SURVEYNAME}\"<br />\n<br />\n\"{SURVEYDESCRIPTION}\"<br />\n<br />\nPer partecipare fare click sul link in basso.<br />\n<br />\nCordiali saluti,{ADMINNAME} ({ADMINEMAIL})<br />\n<br />\n----------------------------------------------<br />\nFare click qui per accedere al questionario e rispondere alle domande relative:<br />\n{SURVEYURL}<br />\n<br />\nSe non si intende partecipare a questa indagine e non si vogliono ricevere altri inviti, si può cliccare sul seguente collegamento:<br />\n{OPTOUTURL}<br />\n<br />\nSe è presente in blacklist ma vuole partecipare a questa indagine e ricevere inviti, vada al seguente link:<br />\n{OPTINURL}','Promemoria per partecipare all\'indagine','Egregio/a {FIRSTNAME},<br />\nRecentemente ha ricevuto un invito a partecipare ad un\'indagine on line.<br />\n<br />\nAbbiamo notato che non ha ancora completato il questionario. Con l\'occasione Le ricordiamo che il questionario è ancora disponibile.<br />\n<br />\nL\'indagine è intitolata:<br />\n\"{SURVEYNAME}\"<br />\n<br />\n\"{SURVEYDESCRIPTION}\"<br />\n<br />\nPer partecipare fare clic sul link qui sotto.<br />\n<br />\nCordiali saluti,<br />\n<br />\n{ADMINNAME} ({ADMINEMAIL})<br />\n<br />\n----------------------------------------------<br />\nFare clic qui per accedere all\'indagine e rispondere al questionario:<br />\n{SURVEYURL}<br />\n<br />\nSe non si intende partecipare a questa indagine e non si vogliono ricevere altri inviti, si può cliccare sul seguente collegamento:<br />\n{OPTOUTURL}','Conferma di registrazione all\'indagine','Egregio/a {FIRSTNAME},<br />\n<br />\nLei (o qualcuno che ha utilizzato il suo indirizzo e-mail) si è registrato per partecipare all\'indagine on line intitolata {SURVEYNAME}.<br />\n<br />\nPer completare il questionario fare clic sul seguente indirizzo:<br />\n<br />\n{SURVEYURL}<br />\n<br />\nSe ha qualche domanda, o se non si è registrato e ritiene che questa e-mail ti sia pervenuta per errore, la preghiamo di contattare  {ADMINNAME} all\'indirizzo {ADMINEMAIL}.','Confermare la partecipazione all&#039;indagine','Egregio/a {FIRSTNAME},<br />\n<br />\nQuesta e-mail le è stata inviata per confermarle che ha completato correttamente il questionario intitolato {SURVEYNAME}  e che le sue risposte sono state salvate. Grazie per la partecipazione.<br />\n<br />\nSe ha ulteriori domande circa questo messaggio, la prego di contattare {ADMINNAME} all\'indirizzo e-mail {ADMINEMAIL}.<br />\n<br />\nCordiali saluti<br />\n<br />\n{ADMINNAME}',5,NULL,'','Invio di una risposta all\'indagine {SURVEYNAME}','Salve,<br />\n<br />\nUna nuova risposta é stata inviata per l\'indagine \'{SURVEYNAME}\'.<br />\n<br />\nFare click sul link seguente per vedere le risposte individuali:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nFare click sul link seguente per modificare le risposte individuali:<br />\n{EDITRESPONSEURL}<br />\n<br />\nFare clic sul link seguente per visualizzare le statistiche:<br />\n{STATISTICSURL}','Invio di una risposta all\'indagine {SURVEYNAME} con risultati','Salve,<br />\n<br />\nUna nuova risposta è stata inviata dall\'indagine \'{SURVEYNAME}\'.<br />\n<br />\nFare clic sul link seguente per vedere la risposta individuale:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nFare clic sul link seguente per modificare la risposta individuale:<br />\n{EDITRESPONSEURL}<br />\n<br />\nFare clic sul link seguente per visualizzare le statistiche:<br />\n{STATISTICSURL}<br />\n<br />\n<br />\nLe seguenti risposte sono state date dal partecipante:<br />\n{ANSWERTABLE}',0,NULL),(282267,'ru','NTICE Образец LimeSurvey EN/FR/DE/IT/RU','В этом опросе представлены все типы вопросов LimeSurvey с некоторыми опциями','','','','','','','','Приглашение к участию в опросе','Уважаемый(-ая) {FIRSTNAME},<br />\n<br />\nприглашаем Вас принять участие в опросе.<br />\n<br />\nОпрос называется<br />\n«‎{SURVEYNAME}»<br />\n<br />\n«‎{SURVEYDESCRIPTION} »<br />\n<br />\nДля участия перейдите по ссылке.<br />\n<br />\nС уважением,<br />\n<br />\n{ADMINNAME} ({ADMINEMAIL})<br />\n<br />\n----------------------------------------------<br />\nНажмите здесь для прохождения опроса:<br />\n{SURVEYURL}<br />\n<br />\nЕсли Вы не хотите участвовать в этом опросе и не хотите больше получать приглашения, перейдите, пожалуйста по следующей ссылке:<br />\n{OPTOUTURL}<br />\n<br />\nЕсли вы внесены в черный список, но хотите участвовать в этом опросе и получать приглашения, перейдите, пожалуйста, по следующей ссылке:<br />\n{OPTINURL}','Напоминание об участии в опросе','Здравствуйте {FIRSTNAME}!<br />\n<br />\nНедавно мы приглашали Вас принять участие в опросе.<br />\n<br />\nПо нашей информации, Вы все еще не прошли опрос. Мы напоминаем Вам, что этот опрос всё ещё доступен, и Вы можете принять в нем участие.<br />\n<br />\nНазвание опроса:<br />\n\"{SURVEYNAME}\"<br />\n<br />\n\"{SURVEYDESCRIPTION}\"<br />\n<br />\nДля того, чтобы принять участие, пожалуйста, перейдите по ссылке.<br />\n<br />\nС уважением,<br />\n<br />\n{ADMINNAME} ({ADMINEMAIL})<br />\n<br />\n----------------------------------------------<br />\nПерейдите по ссылке, чтобы принять участие в опросе:<br />\n{SURVEYURL}<br />\n<br />\nЕсли Вы не хотите участвовать в этом опросе и не хотите больше получать приглашения, перейдите, пожалуйста по следующей ссылке:<br />\n{OPTOUTURL}','Подтверждение регистрации в опросе','Уважаемый {FIRSTNAME}!<br />\n<br />\nВы, либо кто-то другой, используя Ваш адрес E-mail, зарегистрировался для участия в опросе {SURVEYNAME}.<br />\n<br />\nДля участия в этом опросе перейдите по следующей ссылке:<br />\n<br />\n{SURVEYURL}<br />\n<br />\nС уважением,<br />\n<br />\n{ADMINNAME}','Подтверждение вашего участия в нашем опросе','Уважаемый(-ая) {FIRSTNAME}!<br />\n<br />\nНастоящим письмом мы подтверждаем, что вы прошли опрос под названием {SURVEYNAME} и что ваши ответы были сохранены. Благодарим за участие.<br />\n<br />\nЕсли у вас возникнут вопросы по поводу этого письма, свяжитесь с {ADMINNAME} по {ADMINEMAIL}.<br />\n<br />\nС уважением,<br />\n<br />\n{ADMINNAME}',1,NULL,'','Новый ответ для опроса {SURVEYNAME}','Здравствуйте,<br />\n<br />\nНовые ответы были добавлены для опроса \'{SURVEYNAME}\'.<br />\n<br />\nНажмите на ссылку, чтобы увидеть ответы этого респондента:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nИзменить ответы этого респондента можно тут:<br />\n{EDITRESPONSEURL}<br />\n<br />\nПосмотреть статистику ответов можно тут:<br />\n{STATISTICSURL}','Отправка ответа для опроса {SURVEYNAME} с результатами','Здравствуйте,<br />\n<br />\nНовые ответы были добавлены в опросе \'{SURVEYNAME}\'.<br />\n<br />\nНажмите на ссылку, чтобы увидеть ответы этого респондента:<br />\n{VIEWRESPONSEURL}<br />\n<br />\nИзменить ответы этого респондента можно тут:<br />\n{EDITRESPONSEURL}<br />\n<br />\nПосмотреть статистику можно тут:<br />\n{STATISTICSURL}<br />\n<br />\nОтветы были даны следующим участником:<br />\n{ANSWERTABLE}',0,NULL);
